import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Testing-data-consistency.md","filePath":"manual-zh/Testing-data-consistency.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Testing-data-consistency.md"};function s(o,t,c,p,g,i){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h4 id="_5-2-4-检验数据一致性" tabindex="-1">5.2.4 检验数据一致性 <a class="header-anchor" href="#_5-2-4-检验数据一致性" aria-label="Permalink to &quot;5.2.4 检验数据一致性&quot;">​</a></h4><p>对调查数据做的一项合理检查是计算信度。这能让统计人员有一定把握，确信问卷是被认真填写的。如果查看变量 <strong>v1</strong> 、<strong>v3</strong> 和 <strong>v4</strong> 的标签，你会注意到它们提出的问题非常相似。因此，人们会预期这些变量的值（在重新编码之后）彼此高度相关，我们可以用 <code>RELIABILITY</code> 命令（见 <a href="./RELIABILITY">RELIABILITY</a>）来检验这一点。下面的示例展示了一个 PSPP 会话，用户先对负向计分的变量进行重新编码，然后请求针对 <strong>v1</strong> 、<strong>v3</strong> 和 <strong>v4</strong> 的信度统计量。</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/hotel.sav&#39;.
PSPP&gt; compute v3 = 6 - v3.
PSPP&gt; compute v5 = 6 - v5.
PSPP&gt; reliability v1, v3, v4.
</code></pre><p>这将产生如下输出：</p><table tabindex="0"><thead><tr><th>个案数</th><th>N</th><th>百分比</th></tr></thead><tbody><tr><td>有效</td><td>17</td><td>100.0%</td></tr><tr><td>排除</td><td>0</td><td>.0%</td></tr><tr><td>合计</td><td>17</td><td>100.0%</td></tr><tr><td>Cronbach&#39;s Alpha</td><td>项目数</td><td></td></tr><tr><td>.81</td><td>3</td><td></td></tr></tbody></table><p>作为一个经验法则，许多统计人员认为 Cronbach&#39;s Alpha 值达到 0.7 或更高即表示数据可靠。</p><p>此处该值为 0.81，表明变量 <strong>v1</strong> 、<strong>v3</strong> 和 <strong>v4</strong> 之间具有较高程度的信度，因此我们执行的数据及重新编码得到了验证。</p>`,7)])])}const _=a(d,[["render",s]]);export{h as __pageData,_ as default};
